// Ambil item yang SEDANG BERJALAN di Loop saat ini
const activeLoopItem = $('Loop Over Items (Jalur Lama)').item;

const result = [];

for (const item of $input.all()) {
  // 1. Ambil teks dari item.json.output atau fallback ke path lainnya
  const rawText = item.json.output || item.json.content?.parts?.[0]?.text || item.json.text || "";

  // 2. Pembersihan tag Markdown markdown code block jika ada
  const cleanedText = rawText.replace(/```json|```/g, '').trim();

  let parsedData = {};
  try {
    parsedData = JSON.parse(cleanedText);
  } catch(e) {
    parsedData = { 
      is_tor: false, 
      alasan: "Gagal parse JSON Gatekeeper" 
    };
  }

  // 3. Buat objek item baru untuk n8n
  const newItem = {
    json: {
      ...parsedData,
      // Prioritaskan ID & Name dari hasil parse AI, fallback ke activeLoopItem
      file_id: parsedData.file_id || activeLoopItem?.json?.id,
      file_name: parsedData.file_name || activeLoopItem?.json?.name
    }
  };

  // 4. Ambil data binary secara eksplisit jika ada di activeLoopItem
  if (activeLoopItem?.binary) {
    newItem.binary = activeLoopItem.binary;
  }

  result.push(newItem);
}

return result;

// 1. Ambil metadata file dari item loop yang sedang aktif
const activeLoopItem = $('Loop Over Items (Jalur Lama)').item;
const fileId = activeLoopItem.json.id || activeLoopItem.json.file_id || "UNKNOWN_ID";
const fileName = activeLoopItem.json.name || activeLoopItem.json.file_name || "Dokumen Pengadaan";

// 2. Buat wadah utama hasil penggabungan
const mergedOutput = {
  file_id: fileId,
  file_name: fileName,
  reviewer_a: null,
  reviewer_b: null,
  reviewer_c: null
};

// 3. Looping 3 item hasil Append dari Reviewer A, B, dan C
for (const item of $input.all()) {
  // Extract string JSON dari struktur respons Gemini
  const rawText = item.json.candidates?.[0]?.content?.parts?.[0]?.text || item.json.text || "";
  if (!rawText) continue;

  let parsed = {};
  try {
    // Bersihkan format Markdown block ```json ... ``` jika ada
    const cleanText = rawText
      .replace(/^```json\s*/i, "")
      .replace(/^```\s*/i, "")
      .replace(/\s*```$/i, "")
      .trim();
    parsed = JSON.parse(cleanText);
  } catch (e) {
    parsed = { error: "Gagal parse JSON", raw: rawText };
  }

  // Lengkapi file_id di dalam objek parser jika kosong
  parsed.file_id = fileId;

  // 4. Petakan otomatis ke Reviewer A, B, atau C berdasarkan atribut uniknya
  if (parsed.document_validation || parsed.analisis_8_elemen) {
    mergedOutput.reviewer_a = parsed;
  } else if (parsed.overall_score || parsed.reviewer === "B") {
    mergedOutput.reviewer_b = parsed;
  } else if (parsed.risk_level || parsed.reviewer === "C") {
    mergedOutput.reviewer_c = parsed;
  }
}

// 5. Kembalikan 1 item tunggal gabungan ke node selanjutnya (Simpan ke Sheet)
return [{ json: mergedOutput }];

const inputItems = $input.all();
const parsedResults = [];

// 1. Ambil SEMUA data dari node awal untuk referensi pencocokan nama file
let sourceItems = [];
try {
    sourceItems = $('Compare Datasets').all();
} catch (e) {
    try {
        sourceItems = $('Download File').all();
    } catch (err) {
        sourceItems = [];
    }
}

for (const item of inputItems) {
  let targetData = item.json || item;

  // Jika dibungkus dalam array oleh n8n sebelumnya
  if (Array.isArray(targetData)) {
    targetData = targetData[0];
  }

  let rawText = null;

  // Ekstrak teks dari struktur respons Gemini
  if (targetData.content?.parts?.[0]?.text) {
    rawText = targetData.content.parts[0].text;
  } else if (targetData.candidates?.[0]?.content?.parts?.[0]?.text) {
    rawText = targetData.candidates[0].content.parts[0].text;
  } else if (typeof targetData.text === 'string') {
    rawText = targetData.text;
  } else if (targetData.Gate_Status) {
    // Jika data sudah berbentuk objek bersih
    rawText = JSON.stringify(targetData);
  }

  if (!rawText) continue;

  try {
    // Bersihkan format markdown code block jika ada
    const cleanText = rawText
      .replace(/^```json\s*/i, "")
      .replace(/^```\s*/i, "")
      .replace(/\s*```$/i, "")
      .trim();

    const adjudicationResult = JSON.parse(cleanText);

    const fid = adjudicationResult.File_ID || "unknown";

    // 2. Cocokkan nama file asli berdasarkan file_id dari node awal
    let matchingFile = sourceItems.find(s => s.json.id === fid);
    let realFileName = matchingFile ? matchingFile.json.name : (adjudicationResult.File_Name || "Dokumen Pengadaan");

    // Masukkan ke dalam item n8n dengan nama file asli yang sudah match
    parsedResults.push({
      json: {
        file_id: fid,
        file_name: realFileName, // Sekarang dijamin match dengan nama file aslinya!
        file_type: adjudicationResult.File_Type || "",
        gate_status: adjudicationResult.Gate_Status || "REVIEW", // PASS, REVIEW, REJECTED_NOT_TOR, ESCALATE
        tor_completeness_summary: adjudicationResult.TOR_Completeness_Summary || adjudicationResult.TOR_Completeness || "",
        detail_8_elemen: adjudicationResult.Detail_8_Elemen || {},
        status_pengesahan: adjudicationResult.Status_Pengesahan || adjudicationResult.Pengesahan || "",
        spesifikasi_check_synthesis: adjudicationResult.Spesifikasi_Check_Synthesis || adjudicationResult.Spesifikasi_Check || "",
        ai_notes: adjudicationResult.AI_Notes || ""
      }
    });

  } catch (e) {
    parsedResults.push({
      json: {
        error: "Gagal memparsing JSON Adjudicator D",
        raw_output: rawText
      }
    });
  }
}

return parsedResults;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

