const body = $json.body || {};
const username = String(body.username || '');
const password = String(body.password || '');
const adminValid = username === $env.ADMIN_USERNAME && password === $env.ADMIN_PASSWORD;
const userValid = username === $env.USER_USERNAME && password === $env.USER_PASSWORD;

if (adminValid) {
  return [{ json: { success: true, role: 'admin', token: $env.APRUP_AUTH_TOKEN, user: { name: 'Administrator' }, statusCode: 200 } }];
}

if (userValid) {
  return [{ json: { success: true, role: 'user', token: $env.APRUP_AUTH_TOKEN, user: { name: 'Standard User' }, statusCode: 200 } }];
}

return [{ json: { success: false, message: 'Username atau password salah.', statusCode: 401 } }];

