// 1. Ambil ID dari Webhook POST Update Status
const webhookBody = $('Webhook - Update Status Dokumen').first().json.body || {};
const oldTaskId = webhookBody.refer_task_id || "";
const newTaskId = webhookBody.task_id || "";

// 2. Ambil catatan Admin Lama dari Google Sheet
let adminNotesLama = "Tidak ada catatan admin";
let aiNotesD_Lama = "Tidak ada catatan AI lama";
try {
  const sheetOldRow = $('Ambil Data Dokumen Pending1').first().json;
  adminNotesLama = sheetOldRow.Admin_Notes || adminNotesLama;
  aiNotesD_Lama = sheetOldRow.AI_Notes || aiNotesD_Lama;
} catch (e) {
  // Fallback jika baris tidak ditemukan
}

// 3. Ambil log mentah dari MongoDB
const mongoResults = $('Find documents').all();
let oldLog = null;
let newLog = null;

for (const item of mongoResults) {
  if (item.json.task_id === oldTaskId) {
    oldLog = item.json;
  } else if (item.json.task_id === newTaskId) {
    newLog = item.json;
  }
}

// 4. Kirim data gabungan ke AI Pembanding
return [{
  json: {
    old_task_id: oldTaskId,
    new_task_id: newTaskId,
    catatan_admin_lama: adminNotesLama,
    catatan_d_lama: aiNotesD_Lama,
    old_audit_trail: oldLog,
    new_audit_trail: newLog
  }
}];

